export function readFileLayer(file = {}) {
  if (file === null || typeof file !== 'object' || Array.isArray(file)) throw new TypeError('file must be an object');
  const layer = {};
  if (isPlainObject(file.network)) {
    const network = {};
    if (file.network.endpoint !== undefined) network.endpoint = file.network.endpoint;
    if (file.network.retries !== undefined) network.retries = file.network.retries;
    if (Object.keys(network).length) layer.network = network;
  }
  if (isPlainObject(file.ui)) {
    const ui = {};
    if (file.ui.theme !== undefined) ui.theme = file.ui.theme;
    if (file.ui.compact !== undefined) ui.compact = file.ui.compact;
    if (Object.keys(ui).length) layer.ui = ui;
  }
  if (file.enabled !== undefined) layer.enabled = file.enabled;
  return layer;
}
